//! Minimal HTTP/1.1 request-head parsing and response serialization.

use std::io::{self, Write};

/// Response status codes used by the server.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Status {
    Ok,
    Created,
    NoContent,
    BadRequest,
    NotFound,
    MethodNotAllowed,
    RequestTimeout,
    ContentTooLarge,
    HeaderFieldsTooLarge,
    NotImplemented,
    VersionNotSupported,
}

impl Status {
    pub fn code(self) -> u16 {
        match self {
            Self::Ok => 200,
            Self::Created => 201,
            Self::NoContent => 204,
            Self::BadRequest => 400,
            Self::NotFound => 404,
            Self::MethodNotAllowed => 405,
            Self::RequestTimeout => 408,
            Self::ContentTooLarge => 413,
            Self::HeaderFieldsTooLarge => 431,
            Self::NotImplemented => 501,
            Self::VersionNotSupported => 505,
        }
    }

    pub fn reason(self) -> &'static str {
        match self {
            Self::Ok => "OK",
            Self::Created => "Created",
            Self::NoContent => "No Content",
            Self::BadRequest => "Bad Request",
            Self::NotFound => "Not Found",
            Self::MethodNotAllowed => "Method Not Allowed",
            Self::RequestTimeout => "Request Timeout",
            Self::ContentTooLarge => "Content Too Large",
            Self::HeaderFieldsTooLarge => "Request Header Fields Too Large",
            Self::NotImplemented => "Not Implemented",
            Self::VersionNotSupported => "HTTP Version Not Supported",
        }
    }
}

/// A response; always sent with `Content-Length` and `Connection: close`.
#[derive(Debug)]
pub struct Response<'a> {
    pub status: Status,
    pub content_type: Option<&'static str>,
    /// Value of the `Allow` header, set on 405 responses.
    pub allow: Option<&'static str>,
    pub body: &'a [u8],
}

impl<'a> Response<'a> {
    pub fn empty(status: Status) -> Self {
        Self {
            status,
            content_type: None,
            allow: None,
            body: &[],
        }
    }

    pub fn with_body(status: Status, content_type: &'static str, body: &'a [u8]) -> Self {
        Self {
            status,
            content_type: Some(content_type),
            allow: None,
            body,
        }
    }

    pub fn not_allowed(allow: &'static str) -> Self {
        Self {
            allow: Some(allow),
            ..Self::empty(Status::MethodNotAllowed)
        }
    }

    pub fn write_to(&self, w: &mut impl Write) -> io::Result<()> {
        let mut head = format!(
            "HTTP/1.1 {} {}\r\nContent-Length: {}\r\nConnection: close\r\n",
            self.status.code(),
            self.status.reason(),
            self.body.len()
        );
        if let Some(ct) = self.content_type {
            head.push_str("Content-Type: ");
            head.push_str(ct);
            head.push_str("\r\n");
        }
        if let Some(allow) = self.allow {
            head.push_str("Allow: ");
            head.push_str(allow);
            head.push_str("\r\n");
        }
        head.push_str("\r\n");

        if self.body.len() <= 16 * 1024 {
            // Small responses go out in a single write.
            let mut buf = head.into_bytes();
            buf.extend_from_slice(self.body);
            w.write_all(&buf)
        } else {
            w.write_all(head.as_bytes())?;
            w.write_all(self.body)
        }
    }
}

/// A parsed request line plus the header fields the server cares about.
#[derive(Debug, PartialEq, Eq)]
pub struct RequestHead<'a> {
    pub method: &'a [u8],
    pub target: &'a [u8],
    pub content_length: Option<usize>,
}

/// Returns the offset of the CRLFCRLF that terminates the header block.
pub fn find_head_end(buf: &[u8]) -> Option<usize> {
    buf.windows(4).position(|w| w == b"\r\n\r\n")
}

fn is_tchar(c: u8) -> bool {
    c.is_ascii_alphanumeric() || b"!#$%&'*+-.^_`|~".contains(&c)
}

fn is_token(s: &[u8]) -> bool {
    !s.is_empty() && s.iter().copied().all(is_tchar)
}

fn trim_ows(s: &[u8]) -> &[u8] {
    let is_ows = |c: &u8| *c == b' ' || *c == b'\t';
    let start = s.iter().position(|c| !is_ows(c)).unwrap_or(s.len());
    let end = s.iter().rposition(|c| !is_ows(c)).map_or(start, |i| i + 1);
    &s[start..end]
}

/// Parses a non-empty run of ASCII digits, rejecting overflow.
fn parse_decimal(s: &[u8]) -> Option<usize> {
    if s.is_empty() {
        return None;
    }
    s.iter().try_fold(0usize, |acc, &c| {
        let digit = (c as char).to_digit(10)?;
        acc.checked_mul(10)?.checked_add(digit as usize)
    })
}

/// Parses the header block (without the terminating CRLFCRLF).
pub fn parse_head(head: &[u8]) -> Result<RequestHead<'_>, Status> {
    if head.contains(&0) {
        return Err(Status::BadRequest);
    }

    let line_end = head.iter().position(|&c| c == b'\r').unwrap_or(head.len());
    let (line, mut rest) = head.split_at(line_end);

    // Request line: method SP target SP version
    let mut parts = line.splitn(3, |&c| c == b' ');
    let method = parts.next().unwrap_or_default();
    let target = parts.next().ok_or(Status::BadRequest)?;
    let version = parts.next().ok_or(Status::BadRequest)?;
    if method.is_empty() || target.is_empty() || !is_token(method) {
        return Err(Status::BadRequest);
    }
    if version.len() != 8 || !version.starts_with(b"HTTP/1.") {
        return Err(if version.starts_with(b"HTTP/") {
            Status::VersionNotSupported
        } else {
            Status::BadRequest
        });
    }

    let mut content_length = None;
    let mut chunked = false;
    while !rest.is_empty() {
        rest = rest.strip_prefix(b"\r\n").ok_or(Status::BadRequest)?;
        let eol = rest.iter().position(|&c| c == b'\r').unwrap_or(rest.len());
        let (field, tail) = rest.split_at(eol);
        rest = tail;

        let colon = field
            .iter()
            .position(|&c| c == b':')
            .ok_or(Status::BadRequest)?;
        let (name, value) = (&field[..colon], trim_ows(&field[colon + 1..]));
        if !is_token(name) {
            return Err(Status::BadRequest);
        }

        if name.eq_ignore_ascii_case(b"Content-Length") {
            let len = parse_decimal(value).ok_or(Status::BadRequest)?;
            if content_length.is_some_and(|prev| prev != len) {
                return Err(Status::BadRequest);
            }
            content_length = Some(len);
        } else if name.eq_ignore_ascii_case(b"Transfer-Encoding") {
            chunked = true;
        }
    }

    if chunked {
        return Err(if content_length.is_some() {
            Status::BadRequest
        } else {
            Status::NotImplemented
        });
    }
    Ok(RequestHead {
        method,
        target,
        content_length,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_basic_request() {
        let head = parse_head(b"PUT /kv/a HTTP/1.1\r\nHost: x\r\ncontent-length:  5 ").unwrap();
        assert_eq!(head.method, b"PUT");
        assert_eq!(head.target, b"/kv/a");
        assert_eq!(head.content_length, Some(5));
    }

    #[test]
    fn rejects_malformed() {
        assert_eq!(parse_head(b"GET /x"), Err(Status::BadRequest));
        assert_eq!(
            parse_head(b"GET /x HTTP/2.0"),
            Err(Status::VersionNotSupported)
        );
        assert_eq!(parse_head(b"GET /x FOO"), Err(Status::BadRequest));
        assert_eq!(
            parse_head(b"GET /x HTTP/1.1\r\nbad"),
            Err(Status::BadRequest)
        );
        assert_eq!(
            parse_head(b"GET /x HTTP/1.1\r\nContent-Length: 1\r\nContent-Length: 2"),
            Err(Status::BadRequest)
        );
        assert_eq!(
            parse_head(b"GET /x HTTP/1.1\r\nTransfer-Encoding: chunked"),
            Err(Status::NotImplemented)
        );
    }

    #[test]
    fn decimal_overflow() {
        assert_eq!(parse_decimal(b"99999999999999999999999"), None);
        assert_eq!(parse_decimal(b"12"), Some(12));
        assert_eq!(parse_decimal(b"+1"), None);
    }
}

//! kvhttp: a minimal HTTP/1.1 in-memory key-value server.
//!
//! One thread per connection, one request per connection. The store is
//! guarded by a reader-writer lock (see `store`).

mod http;
mod server;
mod store;

use std::net::{Ipv4Addr, TcpListener};
use std::process::ExitCode;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

use crate::store::Store;

/// Pause after a failed `accept` (typically resource exhaustion).
const ACCEPT_BACKOFF: Duration = Duration::from_millis(10);

fn parse_port(s: &str) -> Option<u16> {
    s.parse().ok().filter(|&p| p != 0)
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    let [_, port_arg] = args.as_slice() else {
        let prog = args.first().map_or("kvhttp", String::as_str);
        eprintln!("usage: {prog} <port>");
        return ExitCode::from(2);
    };
    let Some(port) = parse_port(port_arg) else {
        eprintln!("invalid port: {port_arg}");
        return ExitCode::from(2);
    };

    let listener = match TcpListener::bind((Ipv4Addr::LOCALHOST, port)) {
        Ok(listener) => listener,
        Err(e) => {
            eprintln!("bind 127.0.0.1:{port}: {e}");
            return ExitCode::FAILURE;
        }
    };

    let store = Arc::new(Store::new());
    loop {
        let stream = match listener.accept() {
            Ok((stream, _)) => stream,
            Err(e) => {
                eprintln!("accept: {e}");
                thread::sleep(ACCEPT_BACKOFF);
                continue;
            }
        };

        let store = Arc::clone(&store);
        // On failure the closure, and with it the stream, is dropped, which
        // closes the connection.
        if let Err(e) = thread::Builder::new()
            .name("conn".into())
            .spawn(move || server::handle_connection(&store, stream))
        {
            eprintln!("spawn: {e}");
        }
    }
}

//! Connection handling and routing.

use std::io::{self, ErrorKind, Read, Write};
use std::net::{Shutdown, TcpStream};
use std::time::Duration;

use crate::http::{self, RequestHead, Response, Status};
use crate::store::{PutOutcome, Store};

const MAX_HEADER_BYTES: usize = 16 * 1024;
const MAX_KEY_LEN: usize = 64;
const MAX_VALUE_BYTES: usize = 1 << 20;
const IO_TIMEOUT: Duration = Duration::from_secs(10);
/// Upper bound on bytes discarded while waiting for the peer to close.
const DRAIN_LIMIT: u64 = 4 * 1024 * 1024;

/// Serves a single request on `stream`, then closes it gracefully.
pub fn handle_connection(store: &Store, mut stream: TcpStream) {
    // Best effort: failures here only affect timeouts and latency.
    let _ = stream.set_read_timeout(Some(IO_TIMEOUT));
    let _ = stream.set_write_timeout(Some(IO_TIMEOUT));
    let _ = stream.set_nodelay(true);

    // Write errors mean the client went away; there is nobody left to tell.
    let _ = serve(store, &mut stream);
    lingering_close(stream);
}

fn is_timeout(e: &io::Error) -> bool {
    matches!(e.kind(), ErrorKind::WouldBlock | ErrorKind::TimedOut)
}

fn serve(store: &Store, stream: &mut TcpStream) -> io::Result<()> {
    let mut buf = vec![0u8; MAX_HEADER_BYTES];
    let mut used = 0;

    let head_end = loop {
        if used == buf.len() {
            return Response::empty(Status::HeaderFieldsTooLarge).write_to(stream);
        }
        let n = match stream.read(&mut buf[used..]) {
            Ok(0) => return Ok(()),
            Ok(n) => n,
            Err(e) if e.kind() == ErrorKind::Interrupted => continue,
            Err(e) if is_timeout(&e) && used > 0 => {
                return Response::empty(Status::RequestTimeout).write_to(stream);
            }
            Err(_) => return Ok(()),
        };
        // The terminator may straddle the previous read.
        let from = used.saturating_sub(3);
        used += n;
        if let Some(pos) = http::find_head_end(&buf[from..used]) {
            break from + pos;
        }
    };

    let head = match http::parse_head(&buf[..head_end]) {
        Ok(head) => head,
        Err(status) => return Response::empty(status).write_to(stream),
    };
    let extra = &buf[head_end + 4..used];
    route(store, stream, &head, extra)
}

fn valid_key(key: &[u8]) -> bool {
    (1..=MAX_KEY_LEN).contains(&key.len())
        && key
            .iter()
            .all(|&c| c.is_ascii_alphanumeric() || c == b'_' || c == b'-')
}

fn route(
    store: &Store,
    stream: &mut TcpStream,
    req: &RequestHead<'_>,
    extra: &[u8],
) -> io::Result<()> {
    let method = req.method;
    match req.target {
        b"/health" => match method {
            b"GET" => {
                Response::with_body(Status::Ok, "text/plain; charset=utf-8", b"ok").write_to(stream)
            }
            _ => Response::not_allowed("GET").write_to(stream),
        },
        b"/kv" => match method {
            b"GET" => {
                let json = keys_to_json(&store.keys());
                Response::with_body(Status::Ok, "application/json", json.as_bytes())
                    .write_to(stream)
            }
            _ => Response::not_allowed("GET").write_to(stream),
        },
        target => match target.strip_prefix(b"/kv/") {
            Some(key) if !valid_key(key) => Response::empty(Status::BadRequest).write_to(stream),
            Some(key) => {
                // valid_key guarantees ASCII.
                let key = std::str::from_utf8(key).expect("validated key is ASCII");
                match method {
                    b"GET" => match store.get(key) {
                        Some(value) => {
                            Response::with_body(Status::Ok, "application/octet-stream", &value)
                                .write_to(stream)
                        }
                        None => Response::empty(Status::NotFound).write_to(stream),
                    },
                    b"PUT" => handle_put(store, stream, key, req.content_length, extra),
                    b"DELETE" => {
                        let status = if store.delete(key) {
                            Status::NoContent
                        } else {
                            Status::NotFound
                        };
                        Response::empty(status).write_to(stream)
                    }
                    _ => Response::not_allowed("GET, PUT, DELETE").write_to(stream),
                }
            }
            None => Response::empty(Status::NotFound).write_to(stream),
        },
    }
}

fn handle_put(
    store: &Store,
    stream: &mut TcpStream,
    key: &str,
    content_length: Option<usize>,
    extra: &[u8],
) -> io::Result<()> {
    let len = content_length.unwrap_or(0);
    if len > MAX_VALUE_BYTES {
        return Response::empty(Status::ContentTooLarge).write_to(stream);
    }

    let have = extra.len().min(len);
    let mut value = Vec::with_capacity(len);
    value.extend_from_slice(&extra[..have]);
    value.resize(len, 0);
    if stream.read_exact(&mut value[have..]).is_err() {
        return Ok(()); // client went away or timed out
    }

    let status = match store.put(key, value) {
        PutOutcome::Created => Status::Created,
        PutOutcome::Replaced => Status::Ok,
    };
    Response::empty(status).write_to(stream)
}

/// Keys are restricted to `[A-Za-z0-9_-]`, so no JSON escaping is needed.
fn keys_to_json(keys: &[String]) -> String {
    let mut json = String::with_capacity(2 + keys.iter().map(|k| k.len() + 3).sum::<usize>());
    json.push('[');
    for (i, key) in keys.iter().enumerate() {
        if i > 0 {
            json.push(',');
        }
        json.push('"');
        json.push_str(key);
        json.push('"');
    }
    json.push(']');
    json
}

/// Half-closes and drains whatever the peer still sends, so closing the socket
/// does not reset the connection before the client has read the response.
fn lingering_close(mut stream: TcpStream) {
    let _ = stream.flush();
    let _ = stream.shutdown(Shutdown::Write);
    let _ = io::copy(&mut (&mut stream).take(DRAIN_LIMIT), &mut io::sink());
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn key_validation() {
        assert!(valid_key(b"a-Z_09"));
        assert!(valid_key(&[b'k'; 64]));
        assert!(!valid_key(&[b'k'; 65]));
        assert!(!valid_key(b""));
        assert!(!valid_key(b"a/b"));
        assert!(!valid_key(b"bad.key"));
    }

    #[test]
    fn json_list() {
        assert_eq!(keys_to_json(&[]), "[]");
        assert_eq!(keys_to_json(&["a".into(), "b".into()]), r#"["a","b"]"#);
    }
}

//! Thread-safe in-memory key-value store.

use std::collections::BTreeMap;
use std::sync::{Arc, PoisonError, RwLock};

/// Whether a `put` created a new entry or replaced an existing one.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PutOutcome {
    Created,
    Replaced,
}

/// An in-memory map from keys to byte values, guarded by a reader-writer lock.
///
/// Values are reference-counted so readers can hand them out without copying
/// while holding the lock. Keys are kept ordered, so listing is a plain walk.
#[derive(Debug, Default)]
pub struct Store {
    entries: RwLock<BTreeMap<String, Arc<[u8]>>>,
}

impl Store {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn put(&self, key: &str, value: impl Into<Arc<[u8]>>) -> PutOutcome {
        let value = value.into();
        let mut entries = self.entries.write().unwrap_or_else(PoisonError::into_inner);
        match entries.get_mut(key) {
            Some(slot) => {
                *slot = value;
                PutOutcome::Replaced
            }
            None => {
                entries.insert(key.to_owned(), value);
                PutOutcome::Created
            }
        }
    }

    pub fn get(&self, key: &str) -> Option<Arc<[u8]>> {
        let entries = self.entries.read().unwrap_or_else(PoisonError::into_inner);
        entries.get(key).cloned()
    }

    /// Removes `key`, returning whether it was present.
    pub fn delete(&self, key: &str) -> bool {
        let removed = {
            let mut entries = self.entries.write().unwrap_or_else(PoisonError::into_inner);
            entries.remove(key)
        };
        // The value (possibly large) is dropped here, outside the lock.
        removed.is_some()
    }

    /// Returns a snapshot of all keys in ascending order.
    pub fn keys(&self) -> Vec<String> {
        let entries = self.entries.read().unwrap_or_else(PoisonError::into_inner);
        entries.keys().cloned().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn crud() {
        let s = Store::new();
        assert_eq!(s.put("a", b"1".as_slice()), PutOutcome::Created);
        assert_eq!(s.put("a", b"2".as_slice()), PutOutcome::Replaced);
        assert_eq!(s.get("a").as_deref(), Some(b"2".as_slice()));
        assert!(s.delete("a"));
        assert!(!s.delete("a"));
        assert!(s.get("a").is_none());
    }

    #[test]
    fn keys_sorted() {
        let s = Store::new();
        for k in ["b", "a", "C", "_", "-"] {
            s.put(k, Vec::new());
        }
        assert_eq!(s.keys(), ["-", "C", "_", "a", "b"]);
    }
}
